using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 闪电链投射物 — 命中后弹跳至下一最近敌人，共传导4次（命中5个敌人）。
/// 实现 IHomingProjectile 供 HomingProjectileSkillEffect 使用。
/// </summary>
public class StreptomycesProjectile : MonoBehaviour, IHomingProjectile
{
    /// <summary>Static prefab reference for chain spawning.</summary>
    public static GameObject S_StreptoPrefab;

    [Header("Chain Settings")]
    [Tooltip("弹跳搜索半径")]
    [SerializeField] private float _chainJumpRadius = 8f;

    [Header("Visual")]
    [SerializeField] private SpriteRenderer _spriteRenderer;

    [Header("Hit Effect")]
    [SerializeField] private GameObject _hitEffectPrefab;

    [Header("Chain Lightning Arc")]
    [Tooltip("闪电弧段数（锯齿点数 = segments+1）")]
    [SerializeField] private int _arcSegments = 6;
    [Tooltip("闪电弧最大偏移量")]
    [SerializeField] private float _arcJitter = 0.3f;
    [Tooltip("闪电弧持续时间")]
    [SerializeField] private float _arcDuration = 0.15f;
    [Tooltip("闪电弧宽度")]
    [SerializeField] private float _arcWidth = 0.08f;
    [Tooltip("闪电弧材质（电弧 shader），留空则自动加载）")]
    [SerializeField] private Material _arcMaterial;

    private Transform _target;
    private float _speed = 14f;
    private float _damage;
    private Projectile.OwnerType _ownerType;
    private int _jumpsRemaining = 4;
    private HashSet<int> _alreadyHitIds;

    private bool _initialized;

    public void Initialize(Transform target, float speed,
        float casterAttackStrength, float damageMultiplier,
        float totalDamage, Projectile.OwnerType ownerType)
    {
        _target = target;
        _speed = speed > 0 ? speed : 14f;
        _damage = totalDamage;
        _ownerType = ownerType;
        _initialized = true;

        Destroy(gameObject, 4f);
    }

    /// <summary>
    /// 内部用于链弹跳的初始化。
    /// </summary>
    public void InitializeAsChain(Transform target, float speed, float damage,
        Projectile.OwnerType ownerType, int jumpsRemaining, HashSet<int> alreadyHit)
    {
        _target = target;
        _speed = speed;
        _damage = damage;
        _ownerType = ownerType;
        _jumpsRemaining = jumpsRemaining;
        _alreadyHitIds = alreadyHit;
        _initialized = true;

        Destroy(gameObject, 4f);
    }

    void Update()
    {
        if (!_initialized) return;

        if (_target != null)
        {
            Vector2 dir = (_target.position - transform.position).normalized;
            transform.Translate(dir * _speed * Time.deltaTime, Space.World);

            float angle = Mathf.Atan2(dir.y, dir.x) * Mathf.Rad2Deg;
            transform.rotation = Quaternion.Euler(0, 0, angle);
        }
        else
        {
            transform.Translate(Vector2.right * _speed * Time.deltaTime, Space.World);
        }
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!_initialized) return;

        if (other.CompareTag("Obstacles"))
        {
            DestroySelf();
            return;
        }

        string targetTag = _ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        if (!other.CompareTag(targetTag)) return;

        // Deal damage
        var damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
            damageable.TakeDamage(_damage);

        // Mark as hit
        if (_alreadyHitIds == null)
        {
            _alreadyHitIds = new HashSet<int>();
            _alreadyHitIds.Add(gameObject.GetInstanceID()); // skip self projectile
        }
        _alreadyHitIds.Add(other.gameObject.GetInstanceID());

        // Try chain jump
        TryChainJump(other.transform);

        DestroySelf();
    }

    private void TryChainJump(Transform hitTarget)
    {
        if (_jumpsRemaining <= 0) return;

        Transform nextTarget = FindNextTarget(hitTarget.position);
        if (nextTarget == null) return;

        // 生成连锁闪电弧视觉
        SpawnChainLightningArc(hitTarget.position, nextTarget.position);

        // Spawn next chain bolt from the prefab asset
        var go = S_StreptoPrefab != null
            ? Instantiate(S_StreptoPrefab, hitTarget.position, Quaternion.identity)
            : Instantiate(gameObject, hitTarget.position, Quaternion.identity);

        var sb = go.GetComponent<StreptomycesProjectile>();
        if (sb != null)
        {
            sb.InitializeAsChain(nextTarget, _speed, _damage,
                _ownerType, _jumpsRemaining - 1, _alreadyHitIds);
        }
    }

    /// <summary>
    /// 生成锯齿状闪电弧连接两个目标，短暂显示后自动销毁。
    /// </summary>
    private void SpawnChainLightningArc(Vector2 from, Vector2 to)
    {
        float distance = Vector2.Distance(from, to);
        if (distance < 0.01f) return;

        var arcGo = new GameObject("ChainLightningArc");
        arcGo.transform.position = from;

        var lr = arcGo.AddComponent<LineRenderer>();
        lr.useWorldSpace = true;
        lr.positionCount = _arcSegments + 1;
        lr.startWidth = _arcWidth;
        lr.endWidth = _arcWidth * 0.5f;
        lr.numCornerVertices = 0;
        lr.numCapVertices = 2;
        lr.sortingOrder = 25;

        // 使用电弧材质（加法混合）
        Material arcMat = _arcMaterial;
        if (arcMat == null)
        {
            // 从粒子拖尾材质获取电弧 shader 材质
            var trail = transform.Find("TrailParticles");
            if (trail != null)
            {
                var psr = trail.GetComponent<ParticleSystemRenderer>();
                if (psr != null && psr.sharedMaterial != null)
                    arcMat = psr.sharedMaterial;
            }
        }
        if (arcMat == null && _spriteRenderer != null && _spriteRenderer.sharedMaterial != null)
            arcMat = _spriteRenderer.sharedMaterial;

        lr.material = arcMat != null ? arcMat : new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));

        lr.startColor = new Color(0.5f, 1f, 1f, 0.9f);
        lr.endColor = new Color(0.2f, 0.6f, 1f, 0.5f);

        // 生成锯齿点
        Vector2 direction = (to - from).normalized;
        Vector2 perpendicular = new Vector2(-direction.y, direction.x);

        lr.SetPosition(0, from);
        lr.SetPosition(_arcSegments, to);

        for (int i = 1; i < _arcSegments; i++)
        {
            float t = (float)i / _arcSegments;
            Vector2 point = Vector2.Lerp(from, to, t);
            float jitter = (Random.value - 0.5f) * 2f * _arcJitter;
            point += perpendicular * jitter;
            lr.SetPosition(i, point);
        }

        Destroy(arcGo, _arcDuration);
    }

    private Transform FindNextTarget(Vector2 origin)
    {
        string targetTag = _ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        var candidates = GameObject.FindGameObjectsWithTag(targetTag);

        Transform best = null;
        float bestDist = float.MaxValue;
        foreach (var go in candidates)
        {
            if (go.GetComponent<EnemyCore>() is EnemyCore ec && ec.IsDead) continue;
            // Skip already hit
            if (_alreadyHitIds != null && _alreadyHitIds.Contains(go.GetInstanceID())) continue;
            // Skip self
            if ((Vector2)go.transform.position == origin) continue;

            float d = Vector2.SqrMagnitude((Vector2)go.transform.position - origin);
            if (d < bestDist && d < _chainJumpRadius * _chainJumpRadius)
            {
                bestDist = d;
                best = go.transform;
            }
        }
        return best;
    }

    private void DestroySelf()
    {
        if (_hitEffectPrefab != null)
            Instantiate(_hitEffectPrefab, transform.position, Quaternion.identity);

        var trail = transform.Find("TrailParticles");
        if (trail != null)
        {
            trail.SetParent(null);
            var ps = trail.GetComponent<ParticleSystem>();
            if (ps != null)
            {
                ps.Stop(true, ParticleSystemStopBehavior.StopEmitting);
                Destroy(trail.gameObject, ps.main.startLifetime.constantMax + 1f);
            }
            else
            {
                Destroy(trail.gameObject, 2f);
            }
        }

        Destroy(gameObject);
    }

    private void OnBecameInvisible()
    {
        Destroy(gameObject);
    }
}

using UnityEngine;

/// <summary>
/// 投射物型技能效果：生成子弹/火球沿方向飞行，支持散射。
/// 右键 -> Create -> Game -> Skill Effect -> Projectile
/// </summary>
[CreateAssetMenu(fileName = "ProjectileEffect", menuName = "Game/Skill Effect/Projectile")]
public class ProjectileSkillEffect : SkillEffectBase
{
    [Header("投射物配置")]
    [Tooltip("投射物预制体（需挂载 Projectile 组件）")]
    public GameObject projectilePrefab;

    [Tooltip("飞行速度")]
    public float speed = 10f;

    [Tooltip("投射物数量（扇形散射）")]
    public int count = 1;

    [Tooltip("散射角度（仅 count > 1 时生效）")]
    [Range(0f, 180f)] public float spreadAngle = 30f;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        if (projectilePrefab == null)
        {
            Debug.LogWarning("ProjectileSkillEffect: projectilePrefab 为空！");
            return;
        }

        Vector3 spawnPos = caster.CasterTransform.position;
        float baseDamage = caster.GetAttackStrength() * damageMultiplier;

        if (count == 1)
        {
            SpawnOne(spawnPos, direction, baseDamage, speed, ownerType, caster);
        }
        else
        {
            float halfSpread = spreadAngle * 0.5f;
            float angleStep = count > 1 ? spreadAngle / (count - 1) : 0f;
            float baseAngle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;

            for (int i = 0; i < count; i++)
            {
                float angle = baseAngle - halfSpread + angleStep * i;
                Vector2 dir = new Vector2(
                    Mathf.Cos(angle * Mathf.Deg2Rad),
                    Mathf.Sin(angle * Mathf.Deg2Rad));
                SpawnOne(spawnPos, dir, baseDamage, speed, ownerType, caster);
            }
        }
    }

    private void SpawnOne(Vector3 pos, Vector2 dir, float dmg, float spd,
                                  Projectile.OwnerType owner, ISkillCaster caster)
    {
        GameObject go = Instantiate(projectilePrefab, pos, Quaternion.identity);
        Projectile proj = go.GetComponent<Projectile>();
        if (proj == null) proj = go.AddComponent<Projectile>();
        proj.Initialize(dir, spd, dmg, owner, caster.CasterTransform.gameObject);
    }
}

using UnityEngine;

/// <summary>
/// 技能数据资产（ScriptableObject）。
/// 右键 -> Create -> Game -> Skill Data 创建。
/// </summary>
[CreateAssetMenu(fileName = "NewSkill", menuName = "Game/Skill Data")]
public class SkillData : ScriptableObject
{
    [Header("基本信息")]
    public string skillId;          // 唯一标识，如 "fireball"
    public string skillName;        // 显示名称
    [TextArea] public string description;
    public Sprite icon;

    [Header("数值")]
    public float cooldown = 2f;           // 基础冷却时间（秒）
    public float castRange = 10f;         // 施法距离
    public float damageMultiplier = 1.5f; // 伤害系数（乘以施法者攻击力）
    public int maxLevel = 5;              // 最大升级等级

    [Header("效果策略")]
    public SkillEffectBase skillEffect;   // 拖入具体效果资产，如 ProjectileSkillEffect
}

using System;
using UnityEngine;

/// <summary>
/// 技能运行时实例，持有 SkillData + 等级 + 冷却状态。
/// 通过 OnExecute 委托注入具体释放效果。
/// </summary>
public class SkillInstance
{
    public SkillData Data { get; private set; }
    public int Level { get; private set; } = 1;
    public int MaxLevel => Data.maxLevel;
    public bool IsMaxLevel => Level >= MaxLevel;
    public bool IsCoolingDown { get; private set; }

    private float _cooldownRemaining;

    /// <summary>剩余冷却秒数（供 UI 读取）</summary>
    public float CooldownRemaining => _cooldownRemaining;

    /// <summary>冷却进度 0~1，1=满冷却（刚释放），0=冷却完毕（供 UI 读取）</summary>
    public float CooldownPercent
    {
        get
        {
            float total = CurrentCooldown;
            return total > 0f ? Mathf.Clamp01(_cooldownRemaining / total) : 0f;
        }
    }

    /// <summary>当前等级冷却时间（每级减少10%）</summary>
    public float CurrentCooldown => Data.cooldown * (1f - (Level - 1) * 0.1f);

    /// <summary>当前等级伤害系数</summary>
    public float CurrentDamageMultiplier => Data.damageMultiplier * (1f + (Level - 1) * 0.15f);

    /// <summary>技能执行委托：参数为 (施法者, 目标方向)</summary>
    public event Action<ISkillCaster, Vector2> OnExecute;

    internal SkillInstance(SkillData data)
    {
        Data = data;
        Level = 1;
    }

    /// <summary>每帧驱动冷却</summary>
    public void TickCooldown(float deltaTime)
    {
        if (!IsCoolingDown) return;
        _cooldownRemaining -= deltaTime;
        if (_cooldownRemaining <= 0f)
        {
            IsCoolingDown = false;
            _cooldownRemaining = 0f;
        }
    }

    /// <summary>尝试释放技能，返回是否成功</summary>
    public bool TryCast(ISkillCaster caster, Vector2 targetDirection)
    {
        if (IsCoolingDown) return false;

        IsCoolingDown = true;
        _cooldownRemaining = CurrentCooldown;

        OnExecute?.Invoke(caster, targetDirection);
        return true;
    }

    /// <summary>升级技能，返回是否成功</summary>
    public bool TryUpgrade()
    {
        if (IsMaxLevel) return false;
        Level++;
        return true;
    }
}

using UnityEngine;

/// <summary>
/// 技能施法者接口，统一玩家与敌人的技能释放逻辑。
/// </summary>
public interface ISkillCaster
{
    /// <summary>施法者的 Transform</summary>
    Transform CasterTransform { get; }

    /// <summary>获取目标方向（玩家=鼠标方向，敌人=AI逻辑）</summary>
    Vector2 GetTargetDirection();

    /// <summary>获取攻击力，用于技能伤害计算</summary>
    float GetAttackStrength();

    /// <summary>施法者阵营：Player=玩家方（打Enemy） / Enemy=敌方（打Player）</summary>
    Projectile.OwnerType GetOwnerType();
}

using UnityEngine;

/// <summary>
/// 范围伤害技能效果：以施法者或目标点为中心造成圆形范围伤害。
/// 右键 -> Create -> Game -> Skill Effect -> AoE Damage
/// </summary>
[CreateAssetMenu(fileName = "AoEEffect", menuName = "Game/Skill Effect/AoE Damage")]
public class AoESkillEffect : SkillEffectBase
{
    [Header("范围配置")]
    [Tooltip("伤害半径")]
    public float radius = 3f;

    [Tooltip("是否以施法者为中心（否则以施法方向前方2单位处为中心）")]
    public bool centeredOnCaster = true;

    [Tooltip("打击特效预制体（可选）")]
    public GameObject impactVfx;

    [Header("预警（可选）")]
    [Tooltip("预警时间（秒），>0 则延迟生效并播放预警特效")]
    public float warningDuration;

    [Tooltip("预警特效（可选，须配合 warningDuration 使用）")]
    public GameObject warningVfx;

    [Header("眩晕（可选）")]
    [Tooltip("玩家被击中后眩晕时间（秒），0=不眩晕")]
    public float stunDuration;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        Vector2 center = centeredOnCaster
            ? (Vector2)caster.CasterTransform.position
            : (Vector2)caster.CasterTransform.position + direction * 2f;

        float damage = caster.GetAttackStrength() * damageMultiplier;

        MonoBehaviour mono = caster.CasterTransform.GetComponent<MonoBehaviour>();
        if (mono != null)
            mono.StartCoroutine(DelayedExecute(center, damage, ownerType));
        else
            ApplyDamage(center, damage, ownerType);
    }

    private System.Collections.IEnumerator DelayedExecute(Vector2 center,
        float damage, Projectile.OwnerType ownerType)
    {
        if (warningVfx != null)
            Object.Instantiate(warningVfx, center, Quaternion.identity);

        if (warningDuration > 0f)
            yield return new WaitForSeconds(warningDuration);

        ApplyDamage(center, damage, ownerType);
    }

    private void ApplyDamage(Vector2 center, float damage, Projectile.OwnerType ownerType)
    {
        if (impactVfx != null)
            Object.Instantiate(impactVfx, center, Quaternion.identity);

        Collider2D[] hits = Physics2D.OverlapCircleAll(center, radius);
        string enemyTag = ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";

        foreach (var hit in hits)
        {
            if (!hit.CompareTag(enemyTag)) continue;
            if (hit.TryGetComponent<IDamageable>(out var d))
                d.TakeDamage(damage);

            if (stunDuration > 0f && hit.CompareTag("Player")
                && hit.TryGetComponent<PlayerController>(out var pc))
                pc.StartCoroutine(StunRoutine(pc, stunDuration));
        }
    }

    private static System.Collections.IEnumerator StunRoutine(PlayerController pc, float duration)
    {
        pc.InputLocked = true;
        yield return new WaitForSeconds(duration);
        pc.InputLocked = false;
    }
}

using UnityEngine;

/// <summary>
/// 冲刺技能效果：施法者向目标方向瞬移一段距离。
/// 右键 -> Create -> Game -> Skill Effect -> Dash
/// </summary>
[CreateAssetMenu(fileName = "DashEffect", menuName = "Game/Skill Effect/Dash")]
public class DashSkillEffect : SkillEffectBase
{
    [Header("冲刺配置")]
    [Tooltip("冲刺距离")]
    public float distance = 5f;

    [Tooltip("冲刺时间（秒），0 = 瞬间）")]
    public float duration = 0.15f;

    [Tooltip("冲刺过程中是否无敌")]
    public bool invincibleDuringDash = true;

    [Tooltip("冲刺拖影特效预制体（可选）")]
    public GameObject trailVfx;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        MonoBehaviour mono = caster.CasterTransform.GetComponent<MonoBehaviour>();
        if (mono == null) return;

        mono.StartCoroutine(DashRoutine(caster, direction));
    }

    private System.Collections.IEnumerator DashRoutine(ISkillCaster caster, Vector2 dir)
    {
        Transform t = caster.CasterTransform;
        Vector3 start = t.position;
        Vector3 end = start + (Vector3)(dir * distance);
        float elapsed = 0f;

        if (trailVfx != null)
            Instantiate(trailVfx, t.position, Quaternion.identity, t);

        while (elapsed < duration)
        {
            elapsed += Time.deltaTime;
            float tVal = elapsed / duration;
            t.position = Vector3.Lerp(start, end, tVal);
            yield return null;
        }

        t.position = end;
    }
}

using UnityEngine;

/// <summary>
/// 治疗技能效果：恢复施法者自身生命值。
/// 右键 -> Create -> Game -> Skill Effect -> Heal
/// </summary>
[CreateAssetMenu(fileName = "HealEffect", menuName = "Game/Skill Effect/Heal")]
public class HealSkillEffect : SkillEffectBase
{
    [Header("治疗配置")]
    [Tooltip("基础治疗量")]
    public float baseHealAmount = 20f;

    [Tooltip("是否受攻击力加成")]
    public bool scaleWithAttack = true;

    [Tooltip("治疗特效预制体（可选）")]
    public GameObject healVfx;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        float healAmount = scaleWithAttack
            ? baseHealAmount + caster.GetAttackStrength() * damageMultiplier * 0.5f
            : baseHealAmount;

        if (caster.CasterTransform.TryGetComponent<IHealable>(out var healable))
        {
            healable.Heal(healAmount);
        }

        if (healVfx != null)
            Instantiate(healVfx, caster.CasterTransform.position, Quaternion.identity);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 召唤技能：在施法者周围随机位置生成单位。
/// 根据施法者阵营自动选择预制体池、Tag 与目标。
/// </summary>
[CreateAssetMenu(fileName = "SummonEffect", menuName = "Game/Skill Effect/Summon")]
public class SummonSkillEffect : SkillEffectBase
{
    [Header("召唤 — 敌方单位池（Boss/Enemy 释放时使用）")]
    [Tooltip("生成的单位 Tag=Enemy，攻击玩家")]
    public GameObject[] enemyMinionPrefabs;

    [Header("召唤 — 友方单位池（Player 释放时使用）")]
    [Tooltip("生成的单位 Tag=Player，攻击敌人")]
    public GameObject[] playerMinionPrefabs;

    [Header("参数")]
    [Tooltip("召唤数量")]
    public int count = 3;

    [Tooltip("生成半径 (围绕施法者)")]
    public float spawnRadius = 4f;

    [Tooltip("生成间隔 (秒)")]
    public float spawnInterval = 0.3f;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        MonoBehaviour mono = caster.CasterTransform.GetComponent<MonoBehaviour>();
        if (mono == null) return;
        mono.StartCoroutine(SummonRoutine(caster, ownerType));
    }

    private System.Collections.IEnumerator SummonRoutine(ISkillCaster caster, Projectile.OwnerType ownerType)
    {
        GameObject[] pool = ownerType == Projectile.OwnerType.Player
            ? playerMinionPrefabs
            : enemyMinionPrefabs;

        if (pool == null || pool.Length == 0)
        {
            Debug.LogWarning("SummonSkillEffect: 无可用预制体池");
            yield break;
        }

        string targetTag = ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        string selfTag   = ownerType == Projectile.OwnerType.Player ? "Player" : "Enemy";

        Vector2 center = caster.CasterTransform.position;
        Transform parent = caster.CasterTransform.parent;

        for (int i = 0; i < count; i++)
        {
            Vector2 offset = Random.insideUnitCircle * spawnRadius;
            Vector2 spawnPos = center + offset;

            GameObject prefab = pool[Random.Range(0, pool.Length)];
            if (prefab == null) continue;

            var go = Object.Instantiate(prefab, spawnPos, Quaternion.identity, parent);
            go.name = $"Summon_{ownerType}_{i}_{prefab.name}";

            // 阵营标记
            go.tag = selfTag;

            // 设置敌人 Core 的初始目标
            var core = go.GetComponent<EnemyCore>();
            if (core != null)
            {
                var target = FindNearestTarget(spawnPos, targetTag);
                if (target != null)
                    core.PlayerTarget = target; // 字段名是 PlayerTarget，但实际是"攻击目标"
            }

            yield return new WaitForSeconds(spawnInterval);
        }
    }

    private static Transform FindNearestTarget(Vector2 origin, string targetTag)
    {
        var gos = GameObject.FindGameObjectsWithTag(targetTag);
        if (gos == null || gos.Length == 0) return null;

        Transform best = null;
        float bestDist = float.MaxValue;
        foreach (var go in gos)
        {
            float d = Vector2.SqrMagnitude((Vector2)go.transform.position - origin);
            if (d < bestDist)
            {
                bestDist = d;
                best = go.transform;
            }
        }
        return best;
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 通用追踪投射物技能效果 — 搜索范围内最近 N 个敌人，各发射一枚追踪投射物。
/// 具体命中逻辑由投射物预制体（实现 IHomingProjectile）自行处理。
/// </summary>
[CreateAssetMenu(fileName = "HomingProjectileEffect", menuName = "Game/Skill Effect/Homing Projectile")]
public class HomingProjectileSkillEffect : SkillEffectBase
{
    [Header("Projectile")]
    [Tooltip("追踪投射物预制体（需实现 IHomingProjectile）")]
    public GameObject homingProjectilePrefab;

    [Tooltip("投射物飞行速度")]
    public float projectileSpeed = 7f;

    [Tooltip("发射数量")]
    public int projectileCount = 3;

    [Tooltip("敌人搜索半径")]
    public float searchRadius = 10f;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        if (homingProjectilePrefab == null)
        {
            Debug.LogWarning("HomingProjectileSkillEffect: homingProjectilePrefab is null!");
            return;
        }

        // Cache prefab statically for chain reaction (avoids Unity prefab self-reference serialization issue)
        if (BacteriophageProjectile.S_PhagePrefab == null)
            BacteriophageProjectile.S_PhagePrefab = homingProjectilePrefab;
        if (StreptomycesProjectile.S_StreptoPrefab == null)
            StreptomycesProjectile.S_StreptoPrefab = homingProjectilePrefab;

        Vector3 origin = caster.CasterTransform.position;
        float casterAttack = caster.GetAttackStrength();
        float totalDamage = casterAttack * damageMultiplier;

        var enemies = FindNearestEnemies(origin, searchRadius, projectileCount);

        if (enemies.Count == 0)
        {
            Fire(origin, null, totalDamage, casterAttack, damageMultiplier, ownerType);
            return;
        }

        foreach (var enemy in enemies)
        {
            Fire(origin, enemy, totalDamage, casterAttack, damageMultiplier, ownerType);
        }
    }

    private List<Transform> FindNearestEnemies(Vector3 origin, float radius, int maxCount)
    {
        var hits = Physics2D.OverlapCircleAll(origin, radius);
        var result = new List<(Transform t, float d)>();

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            var ec = hit.GetComponent<EnemyCore>();
            if (ec == null || ec.IsDead) continue;
            float d = Vector3.Distance(origin, hit.transform.position);
            result.Add((hit.transform, d));
        }

        result.Sort((a, b) => a.d.CompareTo(b.d));

        var final = new List<Transform>();
        int count = Mathf.Min(maxCount, result.Count);
        for (int i = 0; i < count; i++)
            final.Add(result[i].t);
        return final;
    }

    private void Fire(Vector3 origin, Transform target, float totalDamage,
        float casterAttackStrength, float damageMultiplier,
        Projectile.OwnerType ownerType)
    {
        GameObject go = Instantiate(homingProjectilePrefab, origin, Quaternion.identity);
        var hp = go.GetComponent<IHomingProjectile>();
        if (hp == null)
        {
            Debug.LogWarning($"HomingProjectileSkillEffect: prefab '{go.name}' does not implement IHomingProjectile!");
            return;
        }
        hp.Initialize(target, projectileSpeed, casterAttackStrength,
            damageMultiplier, totalDamage, ownerType);
    }
}

