/// <summary>
/// 玩家技能管理器，挂载在 Player GameObject 上。
/// 管理技能槽位、键位绑定、技能获取/升级/拓展。
/// </summary>
public class PlayerSkillManager : MonoBehaviour, ISkillCaster
{
    [Header("技能槽位")]
    [SerializeField] private List<SkillSlot> _slots = new()
    {
        new SkillSlot { keyBinding = KeyCode.Q },
        new SkillSlot { keyBinding = KeyCode.E },
        new SkillSlot { keyBinding = KeyCode.Z },
        new SkillSlot { keyBinding = KeyCode.X },
    };

    [Header("技能库")]
    [SerializeField] private SkillLibrary _skillLibrary;

    [Header("初始技能")]
    [Tooltip("游戏开始时自动装备的技能 ID（槽位 0~3，留空则不装备）")]
    [SerializeField] private string _initialSkillId0;
    [SerializeField] private string _initialSkillId1;
    [SerializeField] private string _initialSkillId2;
    [SerializeField] private string _initialSkillId3;

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;
    private PlayerStats _stats;

    public Vector2 GetTargetDirection()
    {
        Vector3 mouseWorldPos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mouseWorldPos.z = 0f;
        return (mouseWorldPos - transform.position).normalized;
    }

    public float GetAttackStrength() => _stats != null ? _stats.AttackStrength : 10f;

    public Projectile.OwnerType GetOwnerType() => Projectile.OwnerType.Player;

    // ---------- 委托 ----------
    /// <summary>技能释放事件：参数为 (槽位索引, 技能数据)</summary>
    public event System.Action<int, SkillData> OnSkillCast;
    /// <summary>技能升级事件</summary>
    public event System.Action<int, int> OnSkillUpgraded;

    private void Awake()
    {
        _stats = GetComponent<PlayerStats>();
        EquipInitialSkills();
    }

    private void EquipInitialSkills()
    {
        var ids = new[] { _initialSkillId0, _initialSkillId1, _initialSkillId2, _initialSkillId3 };
        for (int i = 0; i < ids.Length; i++)
        {
            if (!string.IsNullOrEmpty(ids[i]))
                EquipSkill(i, ids[i]);
        }
    }

    void Update()
    {
        for (int i = 0; i < _slots.Count; i++)
        {
            SkillSlot slot = _slots[i];
            slot.Skill?.TickCooldown(Time.deltaTime);

            if (slot.isUnlocked && Input.GetKeyDown(slot.keyBinding))
            {
                CastSkill(i);
            }
        }
    }

    // ---------- 释放 ----------
    private void CastSkill(int index)
    {
        if (index < 0 || index >= _slots.Count) return;
        SkillSlot slot = _slots[index];
        if (!slot.isUnlocked || slot.IsEmpty) return;

        Vector2 direction = GetTargetDirection();

        if (slot.TryCast(this, direction))
        {
            OnSkillCast?.Invoke(index, slot.Skill.Data);
        }
    }

    // ---------- 获取与装备 ----------
    /// <summary>从技能库获取技能并装备到第一个空槽</summary>
    public bool AcquireSkill(string skillId)
    {
        if (_skillLibrary == null) return false;

        SkillInstance instance = _skillLibrary.CreateSkillInstance(skillId);
        return instance != null && EquipToEmptySlot(instance);
    }

    /// <summary>装备技能到指定槽位</summary>
    public bool EquipSkill(int index, string skillId)
    {
        if (_skillLibrary == null) return false;
        if (index < 0 || index >= _slots.Count || !_slots[index].isUnlocked) return false;

        SkillInstance instance = _skillLibrary.CreateSkillInstance(skillId);
        if (instance == null) return false;

        _slots[index].Equip(instance);
        return true;
    }

    /// <summary>装备到第一个空槽</summary>
    public bool EquipToEmptySlot(SkillInstance skill)
    {
        for (int i = 0; i < _slots.Count; i++)
        {
            if (_slots[i].isUnlocked && _slots[i].IsEmpty)
            {
                _slots[i].Equip(skill);
                return true;
            }
        }
        return false;
    }

    // ---------- 升级 ----------
    /// <summary>升级指定槽位技能</summary>
    public bool UpgradeSkill(int index)
    {
        if (index < 0 || index >= _slots.Count) return false;
        SkillSlot slot = _slots[index];
        if (slot.IsEmpty) return false;

        if (slot.Skill.TryUpgrade())
        {
            OnSkillUpgraded?.Invoke(index, slot.Skill.Level);
            return true;
        }
        return false;
    }

    // ---------- 槽位管理 ----------
    /// <summary>拓展技能槽数量</summary>
    public void ExpandSlots(int additionalSlots)
    {
        for (int i = 0; i < additionalSlots; i++)
        {
            _slots.Add(new SkillSlot { keyBinding = KeyCode.None, isUnlocked = true });
        }
    }

    /// <summary>解锁指定槽位</summary>
    public void UnlockSlot(int index)
    {
        if (index >= 0 && index < _slots.Count)
            _slots[index].isUnlocked = true;
    }

    // ---------- 键位 ----------
    /// <summary>重新绑定槽位键位</summary>
    public void RebindKey(int index, KeyCode newKey)
    {
        if (index >= 0 && index < _slots.Count)
            _slots[index].keyBinding = newKey;
    }

    /// <summary>获取槽位技能（供外部查询，如UI）</summary>
    public SkillInstance GetSkill(int index)
    {
        return (index >= 0 && index < _slots.Count) ? _slots[index].Skill : null;
    }

    /// <summary>查询槽位是否解锁（供 UI Controller 读取）</summary>
    public bool IsSlotUnlocked(int index)
    {
        return index >= 0 && index < _slots.Count && _slots[index].isUnlocked;
    }

    /// <summary>获取槽位绑定的快捷键（供 UI Controller 读取）</summary>
    public KeyCode GetKeyCode(int index)
    {
        if (index < 0 || index >= _slots.Count) return KeyCode.None;
        return _slots[index].keyBinding;
    }

    public int SlotCount => _slots.Count;
}

using System;
using UnityEngine;

/// <summary>
/// 敌人生存组件，负责血量管理并通过委托广播变化。
/// 实现 IDamageable 以便外部统一调用。
///
/// 数据源：MaxHealth 由 EnemyCore（或外部）在 Awake 后显式赋值，
///         然后调用 Initialize() 完成初始化。不在 Awake 中自动初始化。
/// </summary>
public class EnemyHealth : MonoBehaviour, IDamageable
{
    [Header("生命")]
    [Tooltip("由 EnemyCore 根据 EnemyConfig 赋值，也可独立设置")]
    public float MaxHealth = 30f;

    private float _health;
    private bool _isDead = false;
    private bool _initialized = false;

    public bool IsDead => _isDead;
    public float CurrentHealth => _health;

    public event Action<float, float> OnHealthChanged;
    public event Action OnDied;
    public event Action<float> OnDamaged;

    /// <summary>
    /// 由 EnemyCore 在设置 MaxHealth 后调用。
    /// 确保 _health 从最终 MaxHealth 初始化，避免数据源不一致。
    /// </summary>
    public void Initialize()
    {
        if (_initialized) return;

        _health = MaxHealth;
        _initialized = true;
    }

    private void Awake()
    {
        // 不再自动初始化，由调用方（EnemyCore）控制初始化时机
    }

    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        _health -= damage;
        _health = Mathf.Max(_health, 0f);

        // 弹出伤害数字
        DamagePopup.Spawn(transform.position, damage);

        OnDamaged?.Invoke(damage);
        OnHealthChanged?.Invoke(_health, MaxHealth);

        if (_health <= 0f)
        {
            Die();
        }
    }

    public void Heal(float amount)
    {
        if (_isDead) return;
        _health = Mathf.Min(_health + amount, MaxHealth);
        OnHealthChanged?.Invoke(_health, MaxHealth);
    }

    private void Die()
    {
        if (_isDead) return;
        _isDead = true;
        OnDied?.Invoke();
    }

    /// <summary>
    /// 清除 OnDied 事件的所有订阅者（用于同化时切换死亡处理逻辑）。
    /// </summary>
    public void ClearOnDied()
    {
        OnDied = null;
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 敌人聚合门面：实现 IEnemy / IDamageable / ISkillCaster，自动收集子组件并负责连线。
/// 所有对外系统（Spawner、技能效果等）应依赖 IEnemy 接口。
/// </summary>
[DisallowMultipleComponent]
public class EnemyCore : MonoBehaviour, IEnemy
{
    [Header("配置")]
    public EnemyConfig config;

    // 子组件
    public EnemyHealth Health { get; private set; }
    public EnemyMovement Movement { get; private set; }
    public EnemySkillManager SkillManager { get; private set; }
    public EnemyStateMachine StateMachine { get; private set; }
    public IAttackBehavior AttackBehavior { get; private set; }

    // 缓存玩家引用 + 最后已知位置（供状态机读取）
    public Transform PlayerTarget { get; set; }
    public Vector2 LastKnownPlayerPosition { get; set; }

    public Transform EnemyTransform => transform;
    public bool IsDead => Health != null && Health.IsDead;
    public bool IsAssimilated { get; private set; }
    public IReadOnlyList<SkillInstance> SkillInstances => SkillManager != null ? SkillManager.SkillInstances : new List<SkillInstance>();
    public event Action OnDied;
    public event Action<IEnemy> OnAssimilated;

    private void Awake()
    {
        Health = GetComponent<EnemyHealth>();
        Movement = GetComponent<EnemyMovement>();
        SkillManager = GetComponent<EnemySkillManager>();
        StateMachine = GetComponent<EnemyStateMachine>();
        AttackBehavior = GetComponent<IAttackBehavior>();

        if (Health == null) Health = gameObject.AddComponent<EnemyHealth>();
        if (Movement == null) Movement = gameObject.AddComponent<EnemyMovement>();
        if (SkillManager == null) SkillManager = gameObject.AddComponent<EnemySkillManager>();
        if (StateMachine == null) StateMachine = gameObject.AddComponent<EnemyStateMachine>();

        // ═══ 单一数据源：EnemyConfig → EnemyCore → 各组件 ═══
        if (config != null)
        {
            if (Health != null)
            {
                Health.MaxHealth = config.maxHealth;
                Health.Initialize();
            }

            if (Movement != null)
                Movement.MoveSpeed = config.patrolSpeed;

            if (SkillManager != null)
                SkillManager.InitializeFromLibrary(config.skillLibrary);
        }
        else if (Health != null)
        {
            // 无 config 时，允许组件自身的 MaxHealth 作为默认值
            Health.Initialize();
        }

        // 绑定死亡事件
        if (Health != null)
        {
            Health.OnDied += () =>
            {
                OnDied?.Invoke();
                // 切换到死亡状态
                if (StateMachine != null)
                    StateMachine.ChangeState(new DeadState(this));
            };
        }
    }

    private void Start()
    {
        var player = GameObject.FindGameObjectWithTag("Player");
        if (player != null) PlayerTarget = player.transform;

        // 启动默认状态（若存在巡逻点则 Patrol，否则 Idle）
        if (StateMachine != null)
        {
            if (config != null && config.patrolPoints != null && config.patrolPoints.Count > 0)
                StateMachine.ChangeState(new PatrolState(this));
            else
                StateMachine.ChangeState(new IdleState(this));
        }
    }

    // ---------- IDamageable (门面) ----------
    public void TakeDamage(float damage)
    {
        if (Health != null)
            Health.TakeDamage(damage);
    }

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;

    public Vector2 GetTargetDirection()
    {
        if (PlayerTarget == null) return Vector2.down;
        return (PlayerTarget.position - transform.position).normalized;
    }

    public float GetAttackStrength()
    {
        // 优先从 MeleeAttack 组件读取伤害值
        if (AttackBehavior is MeleeAttack melee)
            return melee.damage;
        if (AttackBehavior is RangedAttack ranged)
            return ranged.damage;
        return 10f;
    }

    /// <summary>
    /// 施法者阵营：被同化后为 Player（技能命中 Enemy），否则为 Enemy（技能命中 Player）。
    /// </summary>
    public Projectile.OwnerType GetOwnerType() =>
        IsAssimilated ? Projectile.OwnerType.Player : Projectile.OwnerType.Enemy;

    // ---------- 同化 ----------
    /// <summary>
    /// 将被侵蚀的敌人转化为玩家的随从。
    /// - 改 tag 为 Player（让其他敌人的攻击能命中此随从）
    /// - 禁用原状态机，由 EnemyFollower 接管 AI
    /// - 清除旧的死亡事件，由 EnemyFollower 处理死亡
    /// </summary>
    public void Assimilate(Transform playerTarget)
    {
        // 1. 标记已同化（房间/生成器通过 OnAssimilated 事件从存活列表移除）
        IsAssimilated = true;

        // 2. 清除旧的死亡订阅（由 EnemyFollower 接管死亡处理）
        if (Health != null)
            Health.ClearOnDied();

        // 3. 通知外部系统：此敌人不再是敌人
        OnAssimilated?.Invoke(this);

        // 4. 改 tag，使敌人攻击能命中此随从
        gameObject.tag = "Player";

        // 5. 禁用原有状态机
        if (StateMachine != null)
            StateMachine.enabled = false;

        // 6. 停止当前移动
        Movement?.Stop();

        // 7. 添加并激活随从组件
        EnemyFollower follower = GetComponent<EnemyFollower>();
        if (follower == null)
            follower = gameObject.AddComponent<EnemyFollower>();
        follower.Activate(playerTarget);

        // 8. 更新玩家引用（供技能方向等使用）
        PlayerTarget = playerTarget;
    }
}

