/// <summary>
/// 技能效果抽象基类 — 策略模式的核心。
/// 每个具体效果都是一个独立的 ScriptableObject 资产。
/// </summary>
public abstract class SkillEffectBase : ScriptableObject
{
    /// <summary>
    /// 执行技能效果。
    /// </summary>
    /// <param name="caster">施法者接口（玩家或敌人）</param>
    /// <param name="direction">施法方向（已归一化）</param>
    /// <param name="damageMultiplier">经过等级加成后的最终伤害系数</param>
    /// <param name="ownerType">施法者类型，用于投射物区分敌我</param>
    public abstract void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType);
}

using System.Collections.Generic;
using System.Linq;
using UnityEngine;

/// <summary>
/// 技能库（ScriptableObject）—— 所有技能的唯一工厂入口。
/// 右键 -> Create -> Game -> Skill Library 创建。
/// </summary>
[CreateAssetMenu(fileName = "SkillLibrary", menuName = "Game/Skill Library")]
public class SkillLibrary : ScriptableObject
{
    [SerializeField] private List<SkillData> _allSkills;

    /// <summary>所有技能列表</summary>
    public IReadOnlyList<SkillData> AllSkills => _allSkills;

    /// <summary>通过 ID 查找技能数据</summary>
    public SkillData GetById(string skillId)
    {
        return _allSkills?.Find(s => s.skillId == skillId);
    }

    /// <summary>
    /// 创建完整可用的技能实例（SkillLibrary 是唯一工厂入口）。
    /// 通过 skillEffect 策略注入 OnExecute 委托。
    /// </summary>
    public SkillInstance CreateSkillInstance(string skillId)
    {
        SkillData data = GetById(skillId);
        if (data == null)
        {
            Debug.LogWarning($"SkillLibrary: 未找到 skillId='{skillId}'");
            return null;
        }

        SkillInstance instance = new SkillInstance(data);

        instance.OnExecute += (caster, direction) =>
        {
            if (data.skillEffect == null) return;

            Projectile.OwnerType ownerType = caster.GetOwnerType();
            data.skillEffect.Execute(caster, direction,
                instance.CurrentDamageMultiplier, ownerType);
        };

        return instance;
    }

    /// <summary>随机获取一个技能数据</summary>
    public SkillData GetRandom()
    {
        if (_allSkills == null || _allSkills.Count == 0) return null;
        return _allSkills[Random.Range(0, _allSkills.Count)];
    }

    /// <summary>
    /// 随机创建一个完整可用的技能实例（已注入 OnExecute）。
    /// </summary>
    public SkillInstance CreateRandomInstance()
    {
        SkillData data = GetRandom();
        return data != null ? CreateSkillInstance(data.skillId) : null;
    }

    /// <summary>随机获取 N 个不重复的技能数据</summary>
    public List<SkillData> GetRandomDistinct(int count)
    {
        if (_allSkills == null || _allSkills.Count == 0) return new List<SkillData>();

        var shuffled = _allSkills.OrderBy(_ => Random.value).ToList();
        int take = Mathf.Min(count, shuffled.Count);
        return shuffled.GetRange(0, take);
    }
}

using System;
using UnityEngine;

/// <summary>
/// 技能槽位：绑定键位 + 技能实例 + 解锁状态。
/// 在 Inspector 中可配置初始键位。
/// </summary>
[Serializable]
public class SkillSlot
{
    public KeyCode keyBinding = KeyCode.None;
    public bool isUnlocked = true;

    public SkillInstance Skill { get; private set; }
    public bool IsEmpty => Skill == null;

    public void Equip(SkillInstance skill) => Skill = skill;
    public void Unequip() => Skill = null;

    /// <summary>尝试释放槽位中的技能</summary>
    public bool TryCast(ISkillCaster caster, Vector2 direction)
    {
        return Skill != null && Skill.TryCast(caster, direction);
    }
}

using UnityEngine;

/// <summary>
/// 随从行为组件：接管被同化敌人的 AI，跟随玩家 + 搜索并攻击其他敌人。
/// 由 EnemyCore.Assimilate() 激活。
/// </summary>
[RequireComponent(typeof(EnemyCore))]
public class EnemyFollower : MonoBehaviour
{
    [Header("随从参数")]
    [SerializeField] private float _followDistance = 2f;
    [SerializeField] private float _detectionRange = 8f;
    [SerializeField] private float _attackRange = 2f;
    [SerializeField] private float _followSpeed = 3f;
    [Tooltip("离玩家超过此距离时直接传送到身边，防止掉队")]
    [SerializeField] private float _maxTeleportDistance = 12f;

    private Transform _player;
    private EnemyCore _core;
    private EnemyMovement _movement;
    private IAttackBehavior _attackBehavior;
    private EnemySkillManager _skillManager;
    private bool _isActive;

    /// <summary>所有活跃随从列表（供 MapManager 查询，避免 FindObjectsByType）</summary>
    public static readonly System.Collections.Generic.List<EnemyFollower> ActiveFollowers = new();

    private void OnEnable()
    {
        ActiveFollowers.Add(this);

        // 订阅房间切换事件——每次 OnEnable 都重新订阅，确保 SetParent 导致的
        // OnDisable→OnEnable 周期后仍然能响应后续房间切换。
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted += OnRoomSwitchStarted;
    }

    private void OnDisable()
    {
        ActiveFollowers.Remove(this);
        if (_core != null && _core.Health != null)
            _core.Health.OnDied -= HandleDeath;
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted -= OnRoomSwitchStarted;
    }

    private void Awake()
    {
        _core = GetComponent<EnemyCore>();
    }

    /// <summary>
    /// 激活随从模式。
    /// </summary>
    public void Activate(Transform player)
    {
        _player = player;
        _isActive = true;

        _movement = _core.Movement;
        _attackBehavior = _core.AttackBehavior;
        _skillManager = _core.SkillManager;

        if (_movement != null)
            _movement.MoveSpeed = _followSpeed;

        // 远程攻击的随从需要以 OwnerType.Player 发射投射物，才能命中 Enemy tag
        if (_attackBehavior is RangedAttack ranged)
            ranged.projectileOwnerType = Projectile.OwnerType.Player;

        // 近战攻击同样需要切换阵营，避免误伤玩家和其他随从
        if (_attackBehavior is MeleeAttack melee)
            melee.ownerType = Projectile.OwnerType.Player;

        // 接管死亡事件（EnemyCore.Assimilate 已清除原有订阅）
        if (_core.Health != null)
            _core.Health.OnDied += HandleDeath;
    }

    private void Update()
    {
        if (!_isActive || _player == null) return;
        if (_core.Health != null && _core.Health.IsDead) return;

        Vector2 pos = transform.position;
        Vector2 playerPos = _player.position;

        // 离玩家过远 → 直接传送到身边，防止掉队或被卡住
        float sqrDistToPlayer = (pos - playerPos).sqrMagnitude;
        if (sqrDistToPlayer > _maxTeleportDistance * _maxTeleportDistance)
        {
            _movement?.Teleport(playerPos);
            return;
        }

        // 寻找最近的敌人
        Transform nearestEnemy = FindNearestEnemy(pos);

        if (nearestEnemy != null)
        {
            Vector2 enemyPos = nearestEnemy.position;
            float distToEnemy = Vector2.Distance(pos, enemyPos);

            if (distToEnemy <= _attackRange)
            {
                _movement?.Stop();
                _attackBehavior?.TryAttack(nearestEnemy);

                // 尝试释放技能
                if (_skillManager != null && _skillManager.SkillInstances.Count > 0)
                {
                    Vector2 dir = (enemyPos - pos).normalized;
                    _skillManager.TryCastSkill(0, _core, dir);
                }
            }
            else
            {
                _movement?.MoveTowardsPosition(enemyPos);
            }
            return;
        }

        // 没有敌人 → 跟随玩家
        float distToPlayer = Vector2.Distance(pos, playerPos);
        if (distToPlayer > _followDistance)
        {
            _movement?.MoveTowardsPosition(playerPos);
        }
        else
        {
            _movement?.Stop();
        }
    }

    private Transform FindNearestEnemy(Vector2 center)
    {
        Collider2D[] hits = Physics2D.OverlapCircleAll(center, _detectionRange);
        Transform nearest = null;
        float minDist = float.MaxValue;

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            if (_player != null && hit.transform == _player) continue;

            float d = (hit.transform.position - (Vector3)center).sqrMagnitude;
            if (d < minDist)
            {
                minDist = d;
                nearest = hit.transform;
            }
        }

        return nearest;
    }

    private void OnRoomSwitchStarted(int fromRoomId, int toRoomId)
    {
        if (!_isActive || _player == null) return;

        // 1. 将随从切换到新房间的父节点，防止旧房间禁用时连带禁用它
        if (MapManager.Instance != null)
        {
            RoomRoot targetRoom = MapManager.Instance.GetRoom(toRoomId);
            if (targetRoom != null)
                transform.SetParent(targetRoom.transform, true);
        }

        // 2. 立即传送到玩家身边
        _movement?.Teleport(_player.position);
    }

    private void HandleDeath()
    {
        _isActive = false;

        // 禁用碰撞
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = false;

        _movement?.Stop();
        Destroy(gameObject, 0.5f);
    }
}

using System;
using UnityEngine;

public class Projectile : MonoBehaviour
{
    public enum OwnerType { Player, Enemy }

    /// <summary>全局投射物命中事件: (projectile, hitTarget)</summary>
    public static event Action<Projectile, GameObject> OnAnyProjectileHit;

    [Header("子弹参数")]
    [SerializeField] private float speed = 8f;
    [SerializeField] private float damage = 10f;
    [SerializeField] private float lifeTime = 3f;

    /// <summary>投射物所属主人GameObject</summary>
    public GameObject Caster { get; private set; }

    private Vector2 _direction;
    private OwnerType _owner;
    private bool _isInitialized;

    /// <param name="caster">投射物所有者GameObject，可选</param>
    public void Initialize(Vector2 dir, float spd, float dmg, OwnerType owner, GameObject caster = null)
    {
        _direction = dir.normalized;
        speed = spd;
        damage = dmg;
        _owner = owner;
        Caster = caster ?? gameObject;
        _isInitialized = true;

        // 用 Invoke 延时回收（替代 Destroy(gameObject, lifeTime)）
        CancelInvoke(nameof(ReturnToPool));
        Invoke(nameof(ReturnToPool), lifeTime);
    }

    /// <summary>重置状态（池化复用时由 ProjectilePool 间接调用）</summary>
    public void ResetState()
    {
        _isInitialized = false;
        _direction = Vector2.zero;
        Caster = null;
        CancelInvoke(nameof(ReturnToPool));
    }

    void Update()
    {
        if (!_isInitialized) return;
        transform.Translate(_direction * speed * Time.deltaTime, Space.World);
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!_isInitialized) return;

        if (other.CompareTag("Obstacles"))
        {
            ReturnToPool();
            return;
        }

        string targetTag = _owner == OwnerType.Player ? "Enemy" : "Player";
        if (!other.CompareTag(targetTag)) return;

        IDamageable damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            damageable.TakeDamage(damage);
            OnAnyProjectileHit?.Invoke(this, other.gameObject);
        }

        ReturnToPool();
    }

    private void OnBecameInvisible()
    {
        ReturnToPool();
    }

    private void ReturnToPool()
    {
        if (!_isInitialized) return;
        ResetState();
        ProjectilePool.Return(gameObject);
    }
}

using UnityEngine;

/// Homing bacteriophage projectile — flies toward target, marks on hit.
public class BacteriophageProjectile : MonoBehaviour, IHomingProjectile
{
    /// <summary>Static prefab reference for chain spawning (avoids Unity prefab self-reference issues).</summary>
    public static GameObject S_PhagePrefab;

    [Header("Projectile Visual")]
    [SerializeField] private SpriteRenderer _spriteRenderer;

    private Transform _target;
    private float _speed = 6f;
    private float _totalDamage = 40f;
    private Projectile.OwnerType _ownerType;
    private float _casterAttackStrength;
    private float _damageMultiplier;
    private int _totalTicks = 4;
    private float _tickInterval = 1f;
    private int _chainCount = 3;
    private float _chainRadius = 8f;
    private float _chainProjectileSpeed = 6f;

    [Header("Effect Prefabs")]
    [SerializeField] private GameObject _hitEffectPrefab;
    [SerializeField] private GameObject _markVisualPrefab;

    [Header("Chain Reaction")]
    [Tooltip("噬菌体投射物预制体资产（用于死亡传播，非运行时实例）")]
    [SerializeField] private GameObject _phagePrefabAsset;

    private bool _initialized;

    public void Initialize(Transform target, float speed,
        float casterAttackStrength, float damageMultiplier,
        float totalDamage, Projectile.OwnerType ownerType)
    {
        _target = target;
        _speed = speed;
        _totalDamage = totalDamage;
        _ownerType = ownerType;
        _casterAttackStrength = casterAttackStrength;
        _damageMultiplier = damageMultiplier;
        _initialized = true;

        Destroy(gameObject, 5f);
    }

    void Awake()
    {
        // Cache the prefab reference statically (via the serialized _phagePrefabAsset on the prefab)
        if (S_PhagePrefab == null && _phagePrefabAsset != null)
            S_PhagePrefab = _phagePrefabAsset;
    }

    void Update()
    {
        if (!_initialized) return;

        if (_target != null)
        {
            Vector2 direction = (_target.position - transform.position).normalized;
            transform.Translate(direction * _speed * Time.deltaTime, Space.World);

            float angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;
            transform.rotation = Quaternion.Euler(0, 0, angle);
        }
        else
        {
            transform.Translate(Vector2.right * _speed * Time.deltaTime, Space.World);
        }
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!_initialized) return;

        if (other.CompareTag("Obstacles"))
        {
            DestroySelf();
            return;
        }

        string targetTag = _ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        if (!other.CompareTag(targetTag)) return;

        // Hit the correct target — apply mark
        if (other.transform == _target || _target == null)
        {
            ApplyMark(other.gameObject);
        }

        DestroySelf();
    }

    private void ApplyMark(GameObject enemy)
    {
        if (_phagePrefabAsset == null)
            Debug.LogError("[PhageProjectile] _phagePrefabAsset is NULL — chain will not work!");

        var existing = enemy.GetComponent<PhageMarkComponent>();
        if (existing != null)
        {
            // Refresh: destroy old mark, apply new
            Destroy(existing);
        }

        var mark = enemy.AddComponent<PhageMarkComponent>();
        mark.Initialize(_totalDamage, _totalTicks, _tickInterval,
            _chainCount, _chainRadius, _chainProjectileSpeed,
            _phagePrefabAsset, _ownerType,
            _casterAttackStrength, _damageMultiplier,
            _markVisualPrefab);
    }

    private void DestroySelf()
    {
        if (_hitEffectPrefab != null)
        {
            Instantiate(_hitEffectPrefab, transform.position, Quaternion.identity);
        }

        // Detach trail particles and let them dissipate, then destroy
        var trail = transform.Find("TrailParticles");
        if (trail != null)
        {
            trail.SetParent(null);
            var ps = trail.GetComponent<ParticleSystem>();
            if (ps != null)
            {
                ps.Stop(true, ParticleSystemStopBehavior.StopEmitting);
                Destroy(trail.gameObject, ps.main.startLifetime.constantMax + 1f);
            }
            else
            {
                Destroy(trail.gameObject, 2f);
            }
        }

        Destroy(gameObject);
    }

    private void OnBecameInvisible()
    {
        Destroy(gameObject);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 闪电链投射物 — 命中后弹跳至下一最近敌人，共传导4次（命中5个敌人）。
/// 实现 IHomingProjectile 供 HomingProjectileSkillEffect 使用。
/// </summary>
public class StreptomycesProjectile : MonoBehaviour, IHomingProjectile
{
    /// <summary>Static prefab reference for chain spawning.</summary>
    public static GameObject S_StreptoPrefab;

    [Header("Chain Settings")]
    [Tooltip("弹跳搜索半径")]
    [SerializeField] private float _chainJumpRadius = 8f;

    [Header("Visual")]
    [SerializeField] private SpriteRenderer _spriteRenderer;

    [Header("Hit Effect")]
    [SerializeField] private GameObject _hitEffectPrefab;

    [Header("Chain Lightning Arc")]
    [Tooltip("闪电弧段数（锯齿点数 = segments+1）")]
    [SerializeField] private int _arcSegments = 6;
    [Tooltip("闪电弧最大偏移量")]
    [SerializeField] private float _arcJitter = 0.3f;
    [Tooltip("闪电弧持续时间")]
    [SerializeField] private float _arcDuration = 0.15f;
    [Tooltip("闪电弧宽度")]
    [SerializeField] private float _arcWidth = 0.08f;
    [Tooltip("闪电弧材质（电弧 shader），留空则自动加载）")]
    [SerializeField] private Material _arcMaterial;

    private Transform _target;
    private float _speed = 14f;
    private float _damage;
    private Projectile.OwnerType _ownerType;
    private int _jumpsRemaining = 4;
    private HashSet<int> _alreadyHitIds;

    private bool _initialized;

    public void Initialize(Transform target, float speed,
        float casterAttackStrength, float damageMultiplier,
        float totalDamage, Projectile.OwnerType ownerType)
    {
        _target = target;
        _speed = speed > 0 ? speed : 14f;
        _damage = totalDamage;
        _ownerType = ownerType;
        _initialized = true;

        Destroy(gameObject, 4f);
    }

    /// <summary>
    /// 内部用于链弹跳的初始化。
    /// </summary>
    public void InitializeAsChain(Transform target, float speed, float damage,
        Projectile.OwnerType ownerType, int jumpsRemaining, HashSet<int> alreadyHit)
    {
        _target = target;
        _speed = speed;
        _damage = damage;
        _ownerType = ownerType;
        _jumpsRemaining = jumpsRemaining;
        _alreadyHitIds = alreadyHit;
        _initialized = true;

        Destroy(gameObject, 4f);
    }

    void Update()
    {
        if (!_initialized) return;

        if (_target != null)
        {
            Vector2 dir = (_target.position - transform.position).normalized;
            transform.Translate(dir * _speed * Time.deltaTime, Space.World);

            float angle = Mathf.Atan2(dir.y, dir.x) * Mathf.Rad2Deg;
            transform.rotation = Quaternion.Euler(0, 0, angle);
        }
        else
        {
            transform.Translate(Vector2.right * _speed * Time.deltaTime, Space.World);
        }
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!_initialized) return;

        if (other.CompareTag("Obstacles"))
        {
            DestroySelf();
            return;
        }

        string targetTag = _ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        if (!other.CompareTag(targetTag)) return;

        // Deal damage
        var damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
            damageable.TakeDamage(_damage);

        // Mark as hit
        if (_alreadyHitIds == null)
        {
            _alreadyHitIds = new HashSet<int>();
            _alreadyHitIds.Add(gameObject.GetInstanceID()); // skip self projectile
        }
        _alreadyHitIds.Add(other.gameObject.GetInstanceID());

        // Try chain jump
        TryChainJump(other.transform);

        DestroySelf();
    }

    private void TryChainJump(Transform hitTarget)
    {
        if (_jumpsRemaining <= 0) return;

        Transform nextTarget = FindNextTarget(hitTarget.position);
        if (nextTarget == null) return;

        // 生成连锁闪电弧视觉
        SpawnChainLightningArc(hitTarget.position, nextTarget.position);

        // Spawn next chain bolt from the prefab asset
        var go = S_StreptoPrefab != null
            ? Instantiate(S_StreptoPrefab, hitTarget.position, Quaternion.identity)
            : Instantiate(gameObject, hitTarget.position, Quaternion.identity);

        var sb = go.GetComponent<StreptomycesProjectile>();
        if (sb != null)
        {
            sb.InitializeAsChain(nextTarget, _speed, _damage,
                _ownerType, _jumpsRemaining - 1, _alreadyHitIds);
        }
    }

    /// <summary>
    /// 生成锯齿状闪电弧连接两个目标，短暂显示后自动销毁。
    /// </summary>
    private void SpawnChainLightningArc(Vector2 from, Vector2 to)
    {
        float distance = Vector2.Distance(from, to);
        if (distance < 0.01f) return;

        var arcGo = new GameObject("ChainLightningArc");
        arcGo.transform.position = from;

        var lr = arcGo.AddComponent<LineRenderer>();
        lr.useWorldSpace = true;
        lr.positionCount = _arcSegments + 1;
        lr.startWidth = _arcWidth;
        lr.endWidth = _arcWidth * 0.5f;
        lr.numCornerVertices = 0;
        lr.numCapVertices = 2;
        lr.sortingOrder = 25;

        // 使用电弧材质（加法混合）
        Material arcMat = _arcMaterial;
        if (arcMat == null)
        {
            // 从粒子拖尾材质获取电弧 shader 材质
            var trail = transform.Find("TrailParticles");
            if (trail != null)
            {
                var psr = trail.GetComponent<ParticleSystemRenderer>();
                if (psr != null && psr.sharedMaterial != null)
                    arcMat = psr.sharedMaterial;
            }
        }
        if (arcMat == null && _spriteRenderer != null && _spriteRenderer.sharedMaterial != null)
            arcMat = _spriteRenderer.sharedMaterial;

        lr.material = arcMat != null ? arcMat : new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));

        lr.startColor = new Color(0.5f, 1f, 1f, 0.9f);
        lr.endColor = new Color(0.2f, 0.6f, 1f, 0.5f);

        // 生成锯齿点
        Vector2 direction = (to - from).normalized;
        Vector2 perpendicular = new Vector2(-direction.y, direction.x);

        lr.SetPosition(0, from);
        lr.SetPosition(_arcSegments, to);

        for (int i = 1; i < _arcSegments; i++)
        {
            float t = (float)i / _arcSegments;
            Vector2 point = Vector2.Lerp(from, to, t);
            float jitter = (Random.value - 0.5f) * 2f * _arcJitter;
            point += perpendicular * jitter;
            lr.SetPosition(i, point);
        }

        Destroy(arcGo, _arcDuration);
    }

    private Transform FindNextTarget(Vector2 origin)
    {
        string targetTag = _ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        var candidates = GameObject.FindGameObjectsWithTag(targetTag);

        Transform best = null;
        float bestDist = float.MaxValue;
        foreach (var go in candidates)
        {
            if (go.GetComponent<EnemyCore>() is EnemyCore ec && ec.IsDead) continue;
            // Skip already hit
            if (_alreadyHitIds != null && _alreadyHitIds.Contains(go.GetInstanceID())) continue;
            // Skip self
            if ((Vector2)go.transform.position == origin) continue;

            float d = Vector2.SqrMagnitude((Vector2)go.transform.position - origin);
            if (d < bestDist && d < _chainJumpRadius * _chainJumpRadius)
            {
                bestDist = d;
                best = go.transform;
            }
        }
        return best;
    }

    private void DestroySelf()
    {
        if (_hitEffectPrefab != null)
            Instantiate(_hitEffectPrefab, transform.position, Quaternion.identity);

        var trail = transform.Find("TrailParticles");
        if (trail != null)
        {
            trail.SetParent(null);
            var ps = trail.GetComponent<ParticleSystem>();
            if (ps != null)
            {
                ps.Stop(true, ParticleSystemStopBehavior.StopEmitting);
                Destroy(trail.gameObject, ps.main.startLifetime.constantMax + 1f);
            }
            else
            {
                Destroy(trail.gameObject, 2f);
            }
        }

        Destroy(gameObject);
    }

    private void OnBecameInvisible()
    {
        Destroy(gameObject);
    }
}

using UnityEngine;

/// <summary>
/// 投射物型技能效果：生成子弹/火球沿方向飞行，支持散射。
/// 右键 -> Create -> Game -> Skill Effect -> Projectile
/// </summary>
[CreateAssetMenu(fileName = "ProjectileEffect", menuName = "Game/Skill Effect/Projectile")]
public class ProjectileSkillEffect : SkillEffectBase
{
    [Header("投射物配置")]
    [Tooltip("投射物预制体（需挂载 Projectile 组件）")]
    public GameObject projectilePrefab;

    [Tooltip("飞行速度")]
    public float speed = 10f;

    [Tooltip("投射物数量（扇形散射）")]
    public int count = 1;

    [Tooltip("散射角度（仅 count > 1 时生效）")]
    [Range(0f, 180f)] public float spreadAngle = 30f;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        if (projectilePrefab == null)
        {
            Debug.LogWarning("ProjectileSkillEffect: projectilePrefab 为空！");
            return;
        }

        Vector3 spawnPos = caster.CasterTransform.position;
        float baseDamage = caster.GetAttackStrength() * damageMultiplier;

        if (count == 1)
        {
            SpawnOne(spawnPos, direction, baseDamage, speed, ownerType, caster);
        }
        else
        {
            float halfSpread = spreadAngle * 0.5f;
            float angleStep = count > 1 ? spreadAngle / (count - 1) : 0f;
            float baseAngle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;

            for (int i = 0; i < count; i++)
            {
                float angle = baseAngle - halfSpread + angleStep * i;
                Vector2 dir = new Vector2(
                    Mathf.Cos(angle * Mathf.Deg2Rad),
                    Mathf.Sin(angle * Mathf.Deg2Rad));
                SpawnOne(spawnPos, dir, baseDamage, speed, ownerType, caster);
            }
        }
    }

    private void SpawnOne(Vector3 pos, Vector2 dir, float dmg, float spd,
                                  Projectile.OwnerType owner, ISkillCaster caster)
    {
        GameObject go = Instantiate(projectilePrefab, pos, Quaternion.identity);
        Projectile proj = go.GetComponent<Projectile>();
        if (proj == null) proj = go.AddComponent<Projectile>();
        proj.Initialize(dir, spd, dmg, owner, caster.CasterTransform.gameObject);
    }
}

using UnityEngine;

/// <summary>
/// 技能数据资产（ScriptableObject）。
/// 右键 -> Create -> Game -> Skill Data 创建。
/// </summary>
[CreateAssetMenu(fileName = "NewSkill", menuName = "Game/Skill Data")]
public class SkillData : ScriptableObject
{
    [Header("基本信息")]
    public string skillId;          // 唯一标识，如 "fireball"
    public string skillName;        // 显示名称
    [TextArea] public string description;
    public Sprite icon;

    [Header("数值")]
    public float cooldown = 2f;           // 基础冷却时间（秒）
    public float castRange = 10f;         // 施法距离
    public float damageMultiplier = 1.5f; // 伤害系数（乘以施法者攻击力）
    public int maxLevel = 5;              // 最大升级等级

    [Header("效果策略")]
    public SkillEffectBase skillEffect;   // 拖入具体效果资产，如 ProjectileSkillEffect
}

using System;
using UnityEngine;

/// <summary>
/// 技能运行时实例，持有 SkillData + 等级 + 冷却状态。
/// 通过 OnExecute 委托注入具体释放效果。
/// </summary>
public class SkillInstance
{
    public SkillData Data { get; private set; }
    public int Level { get; private set; } = 1;
    public int MaxLevel => Data.maxLevel;
    public bool IsMaxLevel => Level >= MaxLevel;
    public bool IsCoolingDown { get; private set; }

    private float _cooldownRemaining;

    /// <summary>剩余冷却秒数（供 UI 读取）</summary>
    public float CooldownRemaining => _cooldownRemaining;

    /// <summary>冷却进度 0~1，1=满冷却（刚释放），0=冷却完毕（供 UI 读取）</summary>
    public float CooldownPercent
    {
        get
        {
            float total = CurrentCooldown;
            return total > 0f ? Mathf.Clamp01(_cooldownRemaining / total) : 0f;
        }
    }

    /// <summary>当前等级冷却时间（每级减少10%）</summary>
    public float CurrentCooldown => Data.cooldown * (1f - (Level - 1) * 0.1f);

    /// <summary>当前等级伤害系数</summary>
    public float CurrentDamageMultiplier => Data.damageMultiplier * (1f + (Level - 1) * 0.15f);

    /// <summary>技能执行委托：参数为 (施法者, 目标方向)</summary>
    public event Action<ISkillCaster, Vector2> OnExecute;

    internal SkillInstance(SkillData data)
    {
        Data = data;
        Level = 1;
    }

    /// <summary>每帧驱动冷却</summary>
    public void TickCooldown(float deltaTime)
    {
        if (!IsCoolingDown) return;
        _cooldownRemaining -= deltaTime;
        if (_cooldownRemaining <= 0f)
        {
            IsCoolingDown = false;
            _cooldownRemaining = 0f;
        }
    }

    /// <summary>尝试释放技能，返回是否成功</summary>
    public bool TryCast(ISkillCaster caster, Vector2 targetDirection)
    {
        if (IsCoolingDown) return false;

        IsCoolingDown = true;
        _cooldownRemaining = CurrentCooldown;

        OnExecute?.Invoke(caster, targetDirection);
        return true;
    }

    /// <summary>升级技能，返回是否成功</summary>
    public bool TryUpgrade()
    {
        if (IsMaxLevel) return false;
        Level++;
        return true;
    }
}

